
'use strict';
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
const projects=[{id:'a',name:'联合验证',partner:'伙伴 A · 技术生态',done:6,total:8,docs:3,tasks:2,color:'#6488d6',bg:'#edf2ff',icon:'chip',stage:3,start:0,duration:4,block:0},{id:'b',name:'服务合作',partner:'伙伴 B · 部署与成本',done:3,total:8,docs:2,tasks:1,color:'#54a38b',bg:'#eaf5f0',icon:'cloud',stage:2,start:1,duration:4,block:1},{id:'c',name:'技术适配',partner:'伙伴 C · 核心框架',done:5,total:10,docs:4,tasks:1,color:'#9981c3',bg:'#f2eef9',icon:'link',stage:2,start:0,duration:5,block:0},{id:'d',name:'场景探索',partner:'伙伴 D · 应用需求',done:1,total:5,docs:1,tasks:1,color:'#bc985d',bg:'#f8f2e7',icon:'project',stage:1,start:2,duration:3,block:0}];
const tasks=[{id:'t1',name:'伙伴背景研究',project:'a',target:'Mini',done:3,total:5,state:'运行中',steps:['读取资料','归并来源','提取合作线索','验证结论','生成报告']},{id:'t2',name:'试点方案整理',project:'b',target:'Mini',done:1,total:4,state:'等待中',steps:['确认议题','等待输入资料','整理方案','形成待办']},{id:'t3',name:'适配资料索引',project:'c',target:'本机',done:2,total:6,state:'运行中',steps:['检查授权','扫描清单','解析内容','提取标签','构建索引','校验引用']},{id:'t4',name:'会前资料归集',project:'a',target:'Mini',done:4,total:4,state:'已完成',steps:['确认范围','整理来源','去重归档','生成清单']},{id:'t5',name:'需求访谈提纲',project:'d',target:'本机',done:0,total:3,state:'等待中',steps:['等待需求','拟定问题','保存提纲']}];
const pct=(a,b)=>(b?Math.round(a/b*100):0),icon=n=>`<svg class="icon" aria-hidden="true"><use href="#i-${n}"/></svg>`;
function ring(a,b,color='#7395d8',cls='ring'){const p=pct(a,b);return `<svg class="${cls}" viewBox="0 0 80 80" role="img" aria-label="完成 ${a} / ${b}，${p}%"><circle cx="40" cy="40" r="30" fill="none" stroke="#edf0f5" stroke-width="5"/><circle cx="40" cy="40" r="30" fill="none" stroke="${color}" stroke-width="5" stroke-linecap="round" stroke-dasharray="${p*1.885} 188.5" transform="rotate(-90 40 40)"/><text x="40" y="45" text-anchor="middle" font-size="16" font-weight="550" fill="#596c8b">${p}%</text></svg>`}
function metric(label,val,sub,chart){return `<div class="metric"><div><p>${label}</p><b>${val}</b><br><small>${sub}</small></div>${chart||''}</div>`}
function card(p){return `<button class="project surface" data-project="${p.id}"><div class="projecttop"><span class="symbol" style="color:${p.color};background:${p.bg}">${icon(p.icon)}</span>${ring(p.done,p.total,p.color,'mini-ring')}</div><h3>${p.name}</h3><p>${p.partner}</p><div class="steps">${Array.from({length:5},(_,i)=>`<i style="${i<p.stage?'background:'+p.color:''}"></i>`).join('')}</div><div class="projectnumbers"><span><b>${p.done}/${p.total}</b> 交付</span><span><b>${p.docs}</b> 资料</span><span><b>${p.block}</b> 阻塞</span></div></button>`}
function gantt(){return `<div class="gantt"><span class="axis" style="text-align:left">项目 / 交付完成</span>${['10.05','10.12','10.19','10.26','11.02','11.09'].map(x=>`<span class="axis">${x}</span>`).join('')}${projects.map(p=>`<button class="name" data-project="${p.id}">${p.name}<small>${p.done}/${p.total} 项 · ${pct(p.done,p.total)}%</small></button><div class="lane"><button class="bar" data-project="${p.id}" style="left:${p.start/6*100}%;width:${p.duration/6*100}%;background:${p.bg};color:${p.color};border:1px solid ${p.color}35"><span class="diamond"></span>${p.name} · 第 ${p.stage} 阶段</button></div>`).join('')}</div>`}
function composition(){return projects.map(p=>`<button style="width:100%;text-align:left" data-project="${p.id}"><div class="meter"><span>${p.name}</span><i><em style="width:${pct(p.done,p.total)}%;background:${p.color}"></em></i><b>${p.done}/${p.total}</b></div></button>`).join('')+'<p style="font-size:10px;margin-top:22px">已完成 / 全部交付项；未采用主观“健康分”。</p>'}
function taskrow(t){return `<button class="taskrow" data-task="${t.id}"><span class="symbol" style="width:29px;height:29px;background:#f0f4fa;color:${t.state==='等待中'?'#bc985d':'#7595c2'}">${icon(t.state==='已完成'?'task':'chip')}</span><span><strong>${t.name}</strong><small>${projects.find(p=>p.id===t.project).name} · ${t.target} · ${t.state}</small><span class="taskrail">${t.steps.map((_,i)=>`<i class="${i<t.done?'done':''}"></i>`).join('')}</span></span><span style="text-align:right;color:#7a8fae;font-size:12px">${t.done}/${t.total}<small style="display:block">${pct(t.done,t.total)}% 步骤</small></span></button>`}
const total=projects.reduce((s,p)=>s+p.total,0),done=projects.reduce((s,p)=>s+p.done,0);
$('#metrics').innerHTML=metric('推进中的项目',projects.length,'按交付项跟踪',icon('project'))+metric('交付项完成',`${done}/${total}`,'全部项目汇总',ring(done,total))+metric('运行中的任务',tasks.filter(t=>t.state==='运行中').length,'另有 2 项等待',icon('task'))+metric('需要解锁',1,'项目 B · 输入资料',icon('link'));
$('#projectstrip').innerHTML=projects.map(card).join('');$('#roadmap').innerHTML=gantt();$('#taskmini').innerHTML=tasks.slice(0,4).map(taskrow).join('');
let current='home',taskMode='board',target='all',lastFocus=null,toastTimer;
const names={home:['总览','工作台','项目、任务、知识与事务 · 总览提示'],projects:['项目','项目','伙伴、里程碑、资料和任务 · 项目提示'],tasks:['任务','任务','步骤、依赖、执行位置与等待原因 · 任务提示'],knowledge:['知识','知识','研究、简报、资料和记忆 · 知识提示'],personal:['日程与事务','日程与事务','会议、出行与票据 · 事务提示']};
function show(view){current=view;$$('.view').forEach(e=>e.classList.toggle('active',e.id===view));$$('[data-view]').forEach(b=>{b.classList.toggle('active',b.dataset.view===view);b.setAttribute('aria-current',b.dataset.view===view?'page':'false')});$('#crumb').textContent=names[view][0];$('#title').textContent=names[view][1];$('#subtitle').textContent=names[view][2];if(view==='projects')renderProjects('portfolio');if(view==='tasks')renderTasks();if(view==='knowledge')renderKnowledge('topics');if(view==='personal')renderPersonal('calendar')}
function active(group,key,value){$$(group+' button').forEach(b=>{const on=b.dataset[key]===value;b.classList.toggle('active',on);b.setAttribute('aria-pressed',on)})}
function renderProjects(mode){active('#projecttabs','pmode',mode);$('#projectsbody').innerHTML=mode==='portfolio'?`<div class="projectstrip">${projects.map(card).join('')}</div><div class="sectionhead"><h2>交付与阻塞分布</h2></div><div class="surface pad">${composition()}</div>`:`<div class="surface pad">${gantt()}<div class="chartfoot">每条横线表示计划区间，非实际工时；点击展开阶段与任务。</div></div>`}
function renderTasks(){active('#tasktabs','tmode',taskMode);active('#taskfilters','target',target);const ts=tasks.filter(t=>target==='all'||t.target===target);$('#taskmetrics').innerHTML=['运行中','等待中','已完成'].map(s=>metric(s,ts.filter(t=>t.state===s).length,'当前筛选',icon(s==='已完成'?'task':'chip'))).join('')+metric('步骤完成',`${ts.reduce((s,t)=>s+t.done,0)}/${ts.reduce((s,t)=>s+t.total,0)}`,'按步骤数汇总');if(taskMode==='board'){$('#tasksbody').innerHTML=`<div class="kanban">${['等待中','运行中','已完成'].map(s=>`<div class="column"><h3>${s} · ${ts.filter(t=>t.state===s).length}</h3>${ts.filter(t=>t.state===s).map(t=>`<button data-task="${t.id}"><span class="tag">${projects.find(p=>p.id===t.project).name} / ${t.target}</span><h3 style="color:#334664;margin:9px 0">${t.name}</h3>${ring(t.done,t.total)}<p>${t.done} / ${t.total} 步骤 · ${pct(t.done,t.total)}%</p><div class="taskrail">${t.steps.map((_,i)=>`<i class="${i<t.done?'done':''}"></i>`).join('')}</div>${s==='等待中'?'<p style="color:#b0925e">等待输入 · 点击查看条件</p>':''}</button>`).join('')||'<p>当前没有任务</p>'}</div>`).join('')}</div>`}else{$('#tasksbody').innerHTML=`<div class="surface pad"><h2>任务依赖 · 当前筛选</h2><p>节点可点击；每个任务只展示其已声明的输入条件。</p>${ts.map(t=>`<div style="display:grid;grid-template-columns:1fr 30px 1.6fr;align-items:center;margin:20px 0"><span class="chip">${t.state==='等待中'?'等待：资料 / 需求确认':'输入：已选资料版本'}</span><span style="text-align:center;color:#a4b7d1">→</span><div>${taskrow(t)}</div></div>`).join('')}</div>`}}
function renderKnowledge(mode){active('#knowtabs','know',mode);const list={topics:[['推理性能评估','2 个关联项目 · 3 类证据'],['运行环境适配','技术路线与合作切入点'],['评测方法','口径、约束与比较维度']],brief:[['框架能力变化','需验证实际收益 · 示例简报'],['产业合作信号','与当前项目的潜在关联']],files:[['伙伴背景资料','示例文件 · Mini 同步策略'],['会议笔记','示例文件 · 仅本地策略'],['技术路线对比','示例文件 · 版本引用']],memory:[['工作偏好','可查看、纠正与撤回'],['项目背景','保留来源与时间'],['方法沉淀','与业务事实分别管理']]}[mode];$('#knowbody').innerHTML=`<div class="resourcegrid">${list.map(([a,b])=>`<button class="surface resource" data-note="${a}">${icon(mode==='files'?'doc':'knowledge')}<h2>${a}</h2><p>${b}</p><small>示例内容 · 点击展开</small></button>`).join('')}</div><p class="notice">研究、简报、资料和记忆合并为“知识”的二级视图，不再占用四个一级入口。</p>`}
function renderPersonal(mode){active('#personaltabs','personal',mode);$('#personalbody').innerHTML=mode==='calendar'?`<div class="surface pad"><h2>示例日程</h2>${[['10:30','联合验证方案交流'],['14:00','研究与专注时段'],['16:30','试点范围跟进']].map(([a,b])=>`<div class="scheduleline"><time>${a}</time><div><button data-note="${b}"><strong>${b}</strong></button><p>关联机构、项目和资料</p></div></div>`).join('')}</div>`:`<div class="surface pad"><h2>${mode==='travel'?'行程时间线':'票据归档'}</h2><p>此视图预留给${mode==='travel'?'出行安排、会议地点与相关资料':'识别结果、行程或项目关联'}。</p><button class="btn" data-note="${mode==='travel'?'行程接入':'票据接入'}">查看接入范围</button><p class="notice">尚未连接日历、行程或票据服务。</p></div>`}
function open(title,type,html){if(!$('#veil').classList.contains('open'))lastFocus=document.activeElement;$('#detailtitle').textContent=title;$('#detailtype').textContent=type;$('#detailbody').innerHTML=html;$('#veil').classList.add('open');$('.close').focus()}
function close(){$('#veil').classList.remove('open');lastFocus?.focus()}
function projectDetail(id){const p=projects.find(p=>p.id===id),ts=tasks.filter(t=>t.project===id);open(p.name,'PROJECT / 示例项目',`<p>${p.partner} · 按交付项计算进度</p><div style="display:flex;align-items:center;gap:22px;margin-top:20px">${ring(p.done,p.total,p.color)}<div><h3 style="margin:0">已完成 ${p.done} / ${p.total} 项交付</h3><p>剩余 ${p.total-p.done} 项 · ${p.block} 项阻塞</p></div></div><div class="detailmetrics"><div><b>${ts.length}</b><small>关联任务</small></div><div><b>${p.docs}</b><small>参考资料</small></div><div><b>${p.stage}/5</b><small>当前阶段</small></div></div><h3>阶段推进</h3><div class="phase">${['接触','需求','方案','验证','复盘'].map((s,i)=>`<span class="${i<p.stage?'done':''}">${s}</span>`).join('')}</div><h3>关联任务 · 点击继续展开</h3>${ts.map(taskrow).join('')}<h3>交付构成</h3><div class="meter"><span>已完成</span><i><em style="width:${pct(p.done,p.total)}%;background:${p.color}"></em></i><b>${p.done}</b></div><div class="meter"><span>未完成</span><i><em style="width:${pct(p.total-p.done,p.total)}%;background:#bcc8dc"></em></i><b>${p.total-p.done}</b></div>${p.block?'<div class="notice" style="color:#ab884c">阻塞：需要补充试点输入资料，任务尚不能继续。</div>':''}<p class="notice">当前阶段与交付比例是不同维度；全部为示例，不代表实际合作进度。</p>`)}
function taskDetail(id){const t=tasks.find(t=>t.id===id),p=projects.find(p=>p.id===t.project);open(t.name,'TASK / 示例任务',`<p>${p.name} · ${t.target} · ${t.state}</p><div class="detailmetrics"><div><b>${pct(t.done,t.total)}%</b><small>按已完成步骤计算</small></div><div><b>${t.done}/${t.total}</b><small>步骤完成</small></div><div><b>${t.target}</b><small>执行位置 · 示例</small></div></div><h3>执行展开</h3>${t.steps.map((s,i)=>`<div class="evidence"><span style="color:${i<t.done?'#4b9b84':'#8493a9'}">${i<t.done?'✓':'○'} &nbsp; ${i+1}. ${s}</span><span style="color:#9aa6b6">${i<t.done?'已完成':i===t.done?(t.state==='等待中'?'等待输入':'当前步骤'):'未开始'}</span></div>`).join('')}<h3>输入与产物</h3><p>输入：${p.partner} · 指定资料版本</p><p>产物：${t.state==='已完成'?'示例交付清单':'完成后关联回项目'}。尚未生成真实文件。</p><button class="btn" data-project="${p.id}" style="margin-top:16px">返回所属项目</button><p class="notice">均为交互演示，没有连接执行器或创建真实任务。</p>`)}
function note(title){open(title,'CONTEXT / 设计说明','<p>此模块在正式接入后，将展示关联项目、来源、更新时间和下一步行动。</p><h3>信息层级</h3><p>先呈现变化与结论，再按需展开证据与详细记录。</p><p class="notice">当前仅演示页面结构，未检索或修改真实数据。</p>')}
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3500)}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;const d=b.dataset;if(d.view)show(d.view);if(d.goto)show(d.goto);if(d.project)projectDetail(d.project);if(d.task)taskDetail(d.task);if(d.note)note(d.note);if(d.road){active('#roadtabs','road',d.road);$('#roadmap').innerHTML=d.road==='plan'?gantt():composition()}if(d.pmode)renderProjects(d.pmode);if(d.tmode){taskMode=d.tmode;renderTasks()}if(d.target){target=d.target;renderTasks()}if(d.know)renderKnowledge(d.know);if(d.personal)renderPersonal(d.personal)});
$('.close').onclick=close;$('#veil').onclick=e=>{if(e.target===$('#veil'))close()};document.addEventListener('keydown',e=>{if(!$('#veil').classList.contains('open'))return;if(e.key==='Escape')close();if(e.key==='Tab'){const fs=[...$('.drawer').querySelectorAll('button,input,select')].filter(x=>!x.disabled),first=fs[0],last=fs.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}});
$('#settings').onclick=()=>open('空间与设置','SETTINGS / 系统管理','<h3>工作区与设备</h3><p>目录授权、选择性同步、Mini 连接和数据外发策略统一管理。</p><h3>演进提案</h3><p>技术雷达与升级建议收进设置。先讨论，再验证和应用，不占用日常主导航。</p><h3>本次导航逻辑</h3><p>总览：全局态势。项目：业务目标与伙伴。任务：执行单元。知识：研究、简报、资料、记忆。日程与事务：个人安排。</p><p class="notice">此页面不能改变真实配置。</p>');
$('#assistant').onclick=()=>{open('随上下文工作的助理','ASSISTANT / 交互演示','<p>根据当前项目或任务组织上下文；目前没有调用模型。</p><form id="assistantform"><div class="formrow"><input id="prompt" aria-label="助理问题" placeholder="例如：梳理联合验证项目的阻塞点" required></div><button class="btn primary">预览交互</button></form><p id="answer"></p>');$('#assistantform').onsubmit=e=>{e.preventDefault();$('#answer').textContent='演示输入已收到。正式接入后将显示引用、执行步骤与结果。'}};
$('#create').onclick=()=>{open('新建任务','TASK / 仅预览，不执行','<form id="newform"><div class="formrow"><input aria-label="任务名称" placeholder="输入任务名称" required></div><div class="formrow"><label for="projectselect">所属项目</label><select id="projectselect">'+projects.map(p=>`<option>${p.name}</option>`).join('')+'</select></div><div class="formrow"><label for="targetselect">执行位置</label><select id="targetselect"><option>自动建议</option><option>本机</option><option>Mini</option></select></div><button class="btn primary">预览提交</button></form><p class="notice">不会保存或执行真实任务。</p>');$('#newform').onsubmit=e=>{e.preventDefault();toast('已预览任务配置；未调用 DSH、未创建真实任务。')}};
show('home');
